// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testFuzz_property(bytes4 interfaceId) public {
        bool result = c.supportsInterface(interfaceId);
        // The reference contract returns true if interfaceId matches IAccessControl or IERC165.
        // The buggy contract returns true only if both match, which is impossible for distinct interfaces.
        // So for the reference, result should be true for IAccessControl (0x7965b0e8) or IERC165 (0x01ffc9a7).
        vm.assume(interfaceId == type(IAccessControl).interfaceId || interfaceId == type(IERC165).interfaceId);
        assertTrue(result, "supportsInterface should return true for IAccessControl or IERC165");
    }
}

