// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testFuzz_property(bytes32 id, uint256 delay) public {
        vm.assume(delay >= 0 && delay <= 1000000);
        try c.schedule(address(this), 0, "", bytes32(0), id, delay) {
            c.cancel(id);
        } catch {
            // skip if schedule fails
        }
        assertTrue(c.supportsInterface(c.TIMELOCK_ADMIN_ROLE()) == false && c.supportsInterface(c.PROPOSER_ROLE()) == false && c.supportsInterface(c.EXECUTOR_ROLE()) == false);
    }
}

