pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testFuzz_property(bytes32 role, address account) public {
        // Bound account to avoid unrealistic addresses, but we only need address(0) case
        vm.assume(account == address(0));
        // We'll check the rule: supportsInterface for IAccessControl => hasRole(role, address(0)) is false
        // Since in the reference, supportsInterface returns true for IAccessControl
        // In the mutant, it does not, so the rule is: hasRole(role, address(0)) == !c.supportsInterface(type(IAccessControl).interfaceId)
        // But simplify: just assert that if supportsInterface returns false then hasRole(role, address(0)) should be false too
        bool si = c.supportsInterface(type(IAccessControl).interfaceId);
        bool hr = c.hasRole(role, address(0));
        // General rule: The return of supportsInterface for IAccessControl MUST be true
        assertTrue(si == true);
    }
}

