pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testFuzz_property(bytes32 id) public {
        vm.assume(c.isOperationPending(id));
        bool reverted;
        try this.callCancelPublicly(id) { reverted = false; } catch { reverted = true; }
        assertTrue(reverted || c.hasRole(c.TIMELOCK_ADMIN_ROLE(), address(this)));
    }
    function callCancelPublicly(bytes32 id) external {
        c.cancel(id);
    }
}

