pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testFuzz_property(address caller, bytes32 id) public {
        vm.assume(caller != address(0));
        // Ensure the caller is the proposer to potentially succeed
        vm.prank(address(this));
        c.grantRole(c.PROPOSER_ROLE(), caller);

        // Set up a scheduled operation to make cancel possible
        vm.prank(caller);
        c.schedule(address(1), 0, "", bytes32(0), bytes32(0), 1 days);

        // Now try to cancel
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("cancel(bytes32)", id));

        // The general rule: If supportsInterface returns true for IAccessControl, then hasRole(DEFAULT_ADMIN_ROLE, address(0)) must be true
        bool hasIAccessControl = c.supportsInterface(type(IAccessControl).interfaceId);
        bool adminRoleOpen = c.hasRole(c.DEFAULT_ADMIN_ROLE(), address(0));
        assertTrue(hasIAccessControl == adminRoleOpen);
    }
}

