pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }

    function testFuzz_property(bytes32 role) public {
        vm.assume(role != c.DEFAULT_ADMIN_ROLE());

        // Get the expected admin role from the constant
        bytes32 TIMELOCK_ADMIN_ROLE = keccak256("TIMELOCK_ADMIN_ROLE");

        // We need a cancel call that won't revert. 
        // Schedule and then cancel a dummy operation.
        // First, schedule a dummy call
        address target = address(0);
        uint256 value = 0;
        bytes memory data = "";
        bytes32 predecessor = 0;
        bytes32 salt = keccak256(abi.encode(role));
        uint256 delay = 1;
        c.schedule(target, value, data, predecessor, salt, delay);

        // Now cancel it (this requires PROPOSER_ROLE which we have)
        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);
        c.cancel(id);

        // After cancel, verify that getRoleAdmin for PROPOSER_ROLE returns TIMELOCK_ADMIN_ROLE
        bytes32 adminOfProposer = c.getRoleAdmin(c.PROPOSER_ROLE());
        assertTrue(adminOfProposer == TIMELOCK_ADMIN_ROLE, "getRoleAdmin should return the TIMELOCK_ADMIN_ROLE");
    }
}

