// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testFuzz_property(bytes32 id) public {
        // Grant PROPOSER_ROLE to this contract
        bytes32 proposerRole = keccak256("PROPOSER_ROLE");
        vm.prank(address(this));
        c.grantRole(proposerRole, address(this));

        // Schedule an operation so id is pending (otherwise cancel reverts)
        // We don't need to schedule exactly the id, we just need any operation to be pending.
        // For simplicity, schedule a dummy operation with salt = id to make the id match.
        // But the id is arbitrary; we need to make it pending.
        // Instead, we can set up so that the cancel call doesn't revert due to operation not pending.
        // Let's schedule a dummy operation with salt = id (since hashOperation uses salt)
        // However, salt is not exposed in schedule; we can use a unique target/value/data.
        // For fuzzing, we assume id is such that an operation with that id exists or we create it.
        // To avoid complexity, we just attempt to cancel but might revert if not pending.
        // The property is about the impact of cancel on renounceRole; if cancel reverts, it doesn't affect state.
        // So we wrap cancel in try/catch.

        // We'll attempt to cancel id (may revert if not pending)
        (bool cancelSuccess, ) = address(c).call(
            abi.encodeWithSelector(c.cancel.selector, id)
        );

        // Now try to renounce PROPOSER_ROLE for address(this)
        // If the bug is present (M), renounceRole reverts always; if not (P), it succeeds if caller has role.
        // We check if the renounce goes through by calling hasRole before and after.
        bool hadRole = c.hasRole(proposerRole, address(this));

        // Attempt to renounce
        (bool renounceSuccess, ) = address(c).call(
            abi.encodeWithSelector(c.renounceRole.selector, proposerRole, address(this))
        );

        bool stillHasRole = c.hasRole(proposerRole, address(this));

        // The property: if the caller had the role before, then after the renounce attempt,
        // either the renounce succeeded (role removed) or it failed (role still present).
        // In both reference and buggy, the resulting state should be consistent:
        // If renounce succeeded, role is gone; if it reverted, role remains.
        // But the bug makes renounce always revert even if caller is the account.
        // So we assert that if the role was present before, the renounce call either reverted or removed the role.
        // Actually the reference: if hadRole and msg.sender == account, renounce succeeds -> role removed.
        // The mutant: renounce always reverts -> role remains.
        // The general rule: after a cancel (successful or not), a caller who had the role can still attempt renounce.
        // The difference: in reference, if hadRole and caller is account, renounce succeeds; in mutant, it reverts.
        // So we can assert that the renounce call does not revert when it should succeed?
        // But we don't know if caller is account (it is, we are calling as address(this)).
        // So we can assert: if hadRole, then renounce should succeed (role removed) in reference, but fails in mutant.
        // We'll assert that if hadRole, then after renounce call, the role is not present.
        // In reference: true; in mutant: false (due to revert).
        // But the assertion must be true for all fuzz inputs in the reference, false for mutant.
        // Since we only call renounce for the caller (which is allowed), the reference always succeeds if hadRole.
        // So the rule: if the caller had the role before calling renounce for itself, then after the call, it does not have the role.
        // That holds in reference, but in mutant the renounce reverts so the role is still present.

        // To ensure the cancel call does not interfere, we only examine renounce after cancel (even if cancel reverted).
        // The property: if hadRole, then after renounce attempt, the role is removed.
        // However, if renounce reverts, then role is not removed. So in mutant, the property fails.

        if (hadRole) {
            assertTrue(!stillHasRole, "Role should have been removed after renounce");
        }
    }
}

