pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testFuzz_property(bytes32 id) public {
        // Record the timestamp before any operation
        uint256 tsBefore = c.getTimestamp(id);

        // Attempt to cancel — this should only revert if the operation is pending
        // We wrap it to avoid reverting the test
        (bool ok, ) = address(c).call(abi.encodeWithSignature("cancel(bytes32)", id));

        // The rule: If cancel succeeded, then either the operation was pending (and is now done with timestamp 1) 
        // or it was not pending and cancel should have reverted. But we check that the timestamp never goes to 0 
        // from a non-zero value unless scheduled. Specifically:
        // If the operation was not pending (timestamp <= 1), cancel should have reverted (ok == false).
        // If cancel succeeded, then the operation must have been pending and after cancel the timestamp is 0.
        // However, because the private _timestamps cannot be read, we check that after a successful cancel,
        // the timestamp is 0, which is only possible if the original timestamp was > 1 (pending).
        // For any id, the timestamp after cancel should be 0 if cancel succeeded, unchanged if it reverted.

        // Simpler rule: After the call, getTimestamp returns 0 if cancel succeeded, or unchanged if it reverted.
        uint256 tsAfter = c.getTimestamp(id);
        if (ok) {
            // cancel succeeded -> timestamp must be 0
            assertTrue(tsAfter == 0);
        } else {
            // cancel reverted -> timestamp unchanged (no state change)
            assertTrue(tsAfter == tsBefore);
        }
    }
}

